SELECT gen_random_uuid()::text, 'formula', '$\hat{x}$', 'Mode of Grouped Data', '$\hat{x} = L + \frac{d_1}{d_1 + d_2}\,c$', NULL, 'The mode of a frequency table, inside the class with the highest frequency.', '[{"symbol":"$L$","meaning":"lower boundary of the modal class"},{"symbol":"$d_1, d_2$","meaning":"its frequency minus the class before and the class after"},{"symbol":"$c$","meaning":"the class width"}]'::jsonb, 'For raw data the mode is simply the most frequent value; there may be several or none.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Probability & Statistics' AND t."subject" = 'Mathematics' AND s."normKey" = 'central tendency' AND s."active"), NULL, true, 'PENDING', now(), now()
