SELECT gen_random_uuid()::text, 'formula', '$IQR$', 'Quartiles and Interquartile Range', '$Q_k \text{ at position } \tfrac{k(n + 1)}{4};\qquad IQR = Q_3 - Q_1$', NULL, 'The quartiles split sorted data into four equal parts; the IQR is the spread of the middle half.', '[{"symbol":"$Q_1, Q_3$","meaning":"the lower and upper quartiles"},{"symbol":"$n$","meaning":"the number of sorted values"}]'::jsonb, 'An outlier lies beyond $1.5\,IQR$ outside the quartiles. Percentile $P_k$ sits at position $\frac{k(n + 1)}{100}$.', 'Mathematics', t."id", (SELECT s."id" FROM "SyllabusSubtopic" s JOIN "Topic" t ON t."id" = s."topicId" WHERE t."name" = 'Probability & Statistics' AND t."subject" = 'Mathematics' AND s."normKey" = 'dispersion' AND s."active"), NULL, true, 'PENDING', now(), now()
